import json,hashlib
from pathlib import Path
import numpy as np
from gear_sonic.utils.g1_23dof_contract import HARDWARE_23_ACTION_SCALE
root=Path.cwd()
run_root=root/'artifacts/g1_true23_frozen_lora/projection_cost_20260906_v1'
assets=Path('/mnt/z/codex/GR00T-WholeBodyControl')
def identity(p):
 p=Path(p).resolve(strict=True)
 d=hashlib.sha256()
 with p.open('rb') as f:
  for chunk in iter(lambda:f.read(1024*1024),b''):d.update(chunk)
 return {'path':str(p),'sha256':d.hexdigest()}
checked={}
def verify(p,h):
 p=Path(p).resolve(strict=True)
 if str(p) not in checked:checked[str(p)]=identity(p)['sha256']
 if checked[str(p)]!=h:raise ValueError('hash changed: '+str(p))
result={'suites':{},'models':{},'training_files':{}}
for run in ['baseline100','penalty2_100']:
 p=run_root/run
 result['models'][run]={kind:json.loads((p/('eval/model_100.diagnostic.'+kind+'.json')).read_text()) for kind in ['encoder','decoder']}
 lineage=json.loads((p/'lineage.json').read_text())
 for name,group in lineage['materials'].items():
  if not isinstance(group,dict) or 'files' not in group:continue
  for item in group['files']:
   logical=item['logical_path']
   if logical.startswith('causal_recovery/'):
    matches=list((root/'gear_sonic').rglob(Path(logical).name))
    if len(matches)!=1:raise ValueError('ambiguous source: '+logical)
    actual=matches[0]
   elif logical.startswith('unitree_rl_mjlab/'):
    actual=assets/'external_dependencies'/logical
   elif logical.startswith('unitree_g1/'):
    actual=assets/'external_dependencies/unitree_rl_mjlab/src/assets/robots'/logical
   elif logical.startswith('motions/'):
    actual=root/'artifacts/g1_true23_frozen_lora/original_sonic_rehearsal_corpus_v1'/Path(logical).name
   else:actual=root/logical
   verify(actual,item['sha256'])
 result['training_files'][run]={f:identity(p/f) for f in ['resolved_training.json','lineage.json','checkpoints/frozen_lora_model_0.pt','checkpoints/frozen_lora_model_100.pt','environment_prime.json']}
 for family in ['original','stance_v2']:
  summary_path=p/('envelope_'+family)/'suite_summary.json'
  suite=json.loads(summary_path.read_text())
  for item in suite['inputs']:verify(item['path'],item['sha256'])
  rows=[]
  for item in suite['cases']:
   verify(item['summary']['path'],item['summary']['sha256'])
   detail=json.loads(Path(item['summary']['path']).read_text())
   for path,h in detail['sources'].items():verify(path,h)
   for trace in item['trajectories']:verify(trace['path'],trace['sha256'])
   r=item['result']
   with np.load(item['trajectories'][0]['path'],allow_pickle=False) as trace:
    residual=(trace['actuation_requested']-trace['actuation_target'])/np.array(HARDWARE_23_ACTION_SCALE)
    costs=np.square(np.clip(np.nan_to_num(residual,nan=10,posinf=10,neginf=-10),-10,10)).mean(axis=1)
   rows.append({'name':item['name'],'measured':item['measured_start'],'completed':r['completed_transitions'],'requested':r['requested_transitions'],'physics_steps':r['completed_active_physics_steps'],'maximum_joint_rmse_rad':r['maximums'].get('joint_rmse_rad'),'failure':r['failure'],'fidelity_passed':r['motion_fidelity']['passed'],'projection_cost_completed_substeps_mean':float(costs.mean()) if len(costs) else None,'startup_completed':r['startup_hold'].get('completed_transitions'),'startup_passed':r['startup_hold'].get('existing_guard_screen_passed'),'return_completed':r['return_hold'].get('completed_transitions'),'return_physics_steps':r['return_hold'].get('completed_physics_steps'),'return_passed':r['return_hold'].get('existing_guard_screen_passed'),'return_failure':r['return_hold'].get('failure'),'return_failure_details':r['return_hold'].get('failure_details')})
  result['suites'][run+'/'+family]={'summary':identity(summary_path),'clips':suite['reference_clip_count'],'frames':suite['reference_frame_count'],'cases':suite['case_count'],'fidelity_passes':suite['full_clip_motion_fidelity_passed_count'],'lifecycle_passes':suite['paired_lifecycle_screen_passed_count'],'rows':rows}
result['independently_rechecked_unique_files']=len(checked)
result['independently_rechecked_files']=checked
print(json.dumps(result,sort_keys=True))
